/*
    Parallel reduction kernels
*/

#ifndef _REDUCE_KERNEL_H_
#define _REDUCE_KERNEL_H_

#include <cooperative_groups.h>
#include <cooperative_groups/reduce.h>
#include <stdio.h>

namespace cg = cooperative_groups;

// Utility class used to avoid linker errors with extern
// unsized shared memory arrays with templated type
template <class T> struct SharedMemory
{
    __device__ inline operator T *()
    {
        extern __shared__ int __smem[];
        return (T *)__smem;
    }

    __device__ inline operator const T *() const
    {
        extern __shared__ int __smem[];
        return (T *)__smem;
    }
};

// specialize for double to avoid unaligned memory
// access compile errors
template <> struct SharedMemory<double>
{
    __device__ inline operator double *()
    {
        extern __shared__ double __smem_d[];
        return (double *)__smem_d;
    }

    __device__ inline operator const double *() const
    {
        extern __shared__ double __smem_d[];
        return (double *)__smem_d;
    }
};

template <class T> __device__ __forceinline__ T warpReduceSum(unsigned int mask, T mySum)
{
    for (int offset = warpSize / 2; offset > 0; offset /= 2) {
        mySum += __shfl_down_sync(mask, mySum, offset);
    }
    return mySum;
}

#if __CUDA_ARCH__ >= 800
// Specialize warpReduceFunc for int inputs to use __reduce_add_sync intrinsic
// when on SM 8.0 or higher
template <> __device__ __forceinline__ int warpReduceSum<int>(unsigned int mask, int mySum)
{
    mySum = __reduce_add_sync(mask, mySum);
    return mySum;
}
#endif

/*
 * Reduce a warp of signed 64-bit values using four 16-bit limbs. Each limb's
 * sum across 32 lanes fits in int, allowing the existing SM 8.0+ integer warp
 * reduction intrinsic to handle it. The fallback retains the generic 64-bit
 * shuffle reduction on older architectures. Only lane zero's result is used.
 */
__device__ __forceinline__ long long warpReduceSumWide(unsigned int mask,
                                                       long long value,
                                                       unsigned int lane)
{
#if __CUDA_ARCH__ >= 800
    const unsigned long long bits = static_cast<unsigned long long>(value);
    const unsigned int top = static_cast<unsigned int>((bits >> 48) & 0xffffULL);

    const int limb0 = static_cast<int>(bits & 0xffffULL);
    const int limb1 = static_cast<int>((bits >> 16) & 0xffffULL);
    const int limb2 = static_cast<int>((bits >> 32) & 0xffffULL);
    const int limb3 = (top & 0x8000U) ? static_cast<int>(top) - 65536
                                      : static_cast<int>(top);

    const int sum0 = warpReduceSum<int>(mask, limb0);
    const int sum1 = warpReduceSum<int>(mask, limb1);
    const int sum2 = warpReduceSum<int>(mask, limb2);
    const int sum3 = warpReduceSum<int>(mask, limb3);

    if (lane != 0)
        return 0LL;

    return static_cast<long long>(sum0)
         + static_cast<long long>(sum1) * 65536LL
         + static_cast<long long>(sum2) * 4294967296LL
         + static_cast<long long>(sum3) * 281474976710656LL;
#else
    return warpReduceSum<long long>(mask, value);
#endif
}

/*
    Parallel sum reduction using warp reductions and one shared warp-partial
    exchange. Each block retains the 128-thread, one-input-per-lane mapping.
*/
template <class Input, class Output>
__global__ void reduce0(const Input *g_idata, Output *g_odata, unsigned int n)
{
    __shared__ long long warp_sums[4];

    unsigned int tid = threadIdx.x;
    unsigned int lane = tid & 31u;
    unsigned int i = blockIdx.x * blockDim.x + tid;
    long long value = (i < n) ? static_cast<long long>(g_idata[i]) : 0LL;

    const unsigned int mask = 0xffffffffu;
    value = warpReduceSumWide(mask, value, lane);

    unsigned int warp = tid >> 5;
    if (lane == 0)
        warp_sums[warp] = value;

    __syncthreads();

    if (warp == 0) {
        value = (lane < 4) ? warp_sums[lane] : 0LL;
        value = warpReduceSumWide(mask, value, lane);
        if (lane == 0)
            g_odata[blockIdx.x] = static_cast<Output>(value);
    }
}

#endif
extern "C" void run(const void *x, const void *k, const void *gy, void *out,
                    void *scratch, int n, int h, int l, int ks)
{
    if (n == 1) {
        cudaMemcpyAsync(out, x, sizeof(int), cudaMemcpyDeviceToDevice);
        return;
    }

    unsigned int count = static_cast<unsigned int>(n);
    unsigned int max_blocks = (count + 127u) / 128u;
    long long *buffer0 = static_cast<long long *>(scratch);
    long long *buffer1 = buffer0 + max_blocks;
    const int *input32 = static_cast<const int *>(x);
    const long long *input64 = 0;
    bool input_is_wide = false;

    while (count > 1) {
        unsigned int blocks = (count + 127u) / 128u;

        if (blocks == 1) {
            if (input_is_wide) {
                long long *target = (input64 == buffer0) ? buffer1 : buffer0;
                int *result = reinterpret_cast<int *>(target);
                reduce0<long long, int><<<blocks, 128>>>(input64, result, count);
                cudaMemcpyAsync(out, result, sizeof(int), cudaMemcpyDeviceToDevice);
            } else {
                int *result = reinterpret_cast<int *>(buffer0);
                reduce0<int, int><<<blocks, 128>>>(input32, result, count);
                cudaMemcpyAsync(out, result, sizeof(int), cudaMemcpyDeviceToDevice);
            }
            return;
        }

        long long *target;
        if (input_is_wide)
            target = (input64 == buffer0) ? buffer1 : buffer0;
        else
            target = buffer0;

        if (input_is_wide)
            reduce0<long long, long long><<<blocks, 128>>>(input64, target, count);
        else
            reduce0<int, long long><<<blocks, 128>>>(input32, target, count);

        input64 = target;
        input_is_wide = true;
        count = blocks;
    }
}

